-- Companion 0.3: profile customization and a fictional, non-redeemable gift economy.
alter table public.profiles add constraint reserved_creator_username check(username is distinct from 'owner' or role='creator');
alter table public.profiles add column header_style text not null default 'ocean' check(header_style in ('ocean','sunset','lilac','mint','midnight'));
alter table public.profiles add constraint avatar_length check(char_length(avatar_url)<=500), add constraint cover_length check(char_length(cover_url)<=500);
grant update(header_style) on public.profiles to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('profile-media','profile-media',true,2097152,array['image/jpeg','image/png','image/webp']);
create policy "profile media insert" on storage.objects for insert to authenticated with check(bucket_id='profile-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "profile media read own" on storage.objects for select to authenticated using(bucket_id='profile-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "profile media update own" on storage.objects for update to authenticated using(bucket_id='profile-media' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='profile-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "profile media delete own" on storage.objects for delete to authenticated using(bucket_id='profile-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create table public.wallets(user_id uuid primary key references public.profiles(id) on delete cascade, stars bigint not null default 1000 check(stars>=0),ton_milli bigint not null default 10000 check(ton_milli>=0));
alter table public.wallets enable row level security;
revoke all on public.wallets from anon,authenticated;
grant select on public.wallets to authenticated;
create policy "own demo balance" on public.wallets for select to authenticated using(user_id=(select auth.uid()));
insert into public.wallets(user_id) select id from public.profiles;
create function companion_private.new_wallet() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.wallets(user_id) values(new.id); return new; end $$;
revoke all on function companion_private.new_wallet() from public,anon,authenticated;
create trigger companion_wallet after insert on public.profiles for each row execute function companion_private.new_wallet();
create table public.gift_catalog(id text primary key,name text not null,image text not null,stars integer not null check(stars>0),ton_milli integer not null check(ton_milli>0),active boolean not null default true);
alter table public.gift_catalog enable row level security;
revoke all on public.gift_catalog from anon,authenticated;
grant select on public.gift_catalog to authenticated;
create policy "view gift catalog" on public.gift_catalog for select to authenticated using(active);
create table public.profile_gifts(id uuid primary key default gen_random_uuid(),gift_id text not null references public.gift_catalog(id),sender uuid not null references public.profiles(id),recipient uuid not null references public.profiles(id),note text not null default '' check(char_length(note)<=200),currency text not null check(currency in ('stars','ton')),amount integer not null check(amount>0),hidden boolean not null default false,request_id uuid not null,created_at timestamptz not null default now(),unique(sender,request_id));
alter table public.profile_gifts enable row level security;
revoke all on public.profile_gifts from anon,authenticated;
grant select on public.profile_gifts to authenticated;
grant update(hidden) on public.profile_gifts to authenticated;
create policy "public showcase or participants" on public.profile_gifts for select to authenticated using(not hidden or sender=(select auth.uid()) or recipient=(select auth.uid()));
create policy "recipient sets visibility" on public.profile_gifts for update to authenticated using(recipient=(select auth.uid())) with check(recipient=(select auth.uid()));
create index profile_gifts_recipient_time on public.profile_gifts(recipient,created_at desc);
create index profile_gifts_sender on public.profile_gifts(sender);
create function companion_private.purchase_gift(item text,target uuid,pay_with text,message text,request uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); w public.wallets; g public.gift_catalog; result uuid; creator boolean; price integer;
begin
 if uid is null then raise exception 'Войдите в аккаунт'; end if;
 select role='creator' into creator from public.profiles where id=uid;
 if creator is null then raise exception 'Аккаунт не найден'; end if;
 if char_length(message)>200 then raise exception 'Подпись до 200 символов'; end if;
 if not exists(select 1 from public.profiles where id=target) then raise exception 'Получатель не найден'; end if;
 select * into g from public.gift_catalog where id=item and active;
 if not found then raise exception 'Подарок недоступен'; end if;
 if pay_with not in ('stars','ton') then raise exception 'Неизвестный тестовый баланс'; end if;
 select * into w from public.wallets where user_id=uid for update;
 if not found then raise exception 'Баланс не найден'; end if;
 select id into result from public.profile_gifts where sender=uid and request_id=request;
 if result is not null then return result; end if;
 price:=case when pay_with='stars' then g.stars else g.ton_milli end;
 if not creator then
  if (pay_with='stars' and w.stars<price) or (pay_with='ton' and w.ton_milli<price) then raise exception 'Недостаточно тестовых средств'; end if;
  update public.wallets set stars=stars-case when pay_with='stars' then price else 0 end,ton_milli=ton_milli-case when pay_with='ton' then price else 0 end where user_id=uid;
 end if;
 insert into public.profile_gifts(gift_id,sender,recipient,note,currency,amount,request_id) values(item,uid,target,coalesce(message,''),pay_with,price,request) returning id into result;
 return result;
end $$;
revoke all on function companion_private.purchase_gift(text,uuid,text,text,uuid) from public,anon;
grant usage on schema companion_private to authenticated;
grant execute on function companion_private.purchase_gift(text,uuid,text,text,uuid) to authenticated;
create function public.purchase_gift(item text,target uuid,pay_with text,message text,request uuid) returns uuid language sql security invoker set search_path='' as $$ select companion_private.purchase_gift(item,target,pay_with,message,request) $$;
revoke all on function public.purchase_gift(text,uuid,text,text,uuid) from public,anon;
grant execute on function public.purchase_gift(text,uuid,text,text,uuid) to authenticated;
